const duaShareCopy={share:['Duanı paylaş','Duayı paylaş','Поделиться дуа','Share dua','مشاركة الدعاء'],image:['Şəkil kimi paylaş','Görsel olarak paylaş','Поделиться изображением','Share image','مشاركة الصورة'],text:['Mətn kimi paylaş','Metin olarak paylaş','Поделиться текстом','Share text','مشاركة النص'],copy:['Mətni kopyala','Metni kopyala','Копировать текст','Copy text','نسخ النص'],status:['WhatsApp statusu üçün şəkil paylaşımını seçin, açılan menyuda WhatsApp → Statusum seçə bilərsiniz. Yalnız seçilmiş dua paylaşılır.','WhatsApp durumu için görsel paylaşın; açılan menüden WhatsApp → Durumum seçebilirsiniz. Yalnız seçili dua paylaşılır.','Для статуса выберите изображение, затем WhatsApp → Мой статус. Передаётся только выбранное дуа.','For a WhatsApp status, share the image and choose WhatsApp → My status. Only the selected dua is shared.','لحالة واتساب شارك الصورة ثم اختر واتساب ← حالتي. يُشارك الدعاء المحدد فقط.'],copied:['Mətn kopyalandı','Metin kopyalandı','Текст скопирован','Text copied','نُسخ النص'],fallback:['Paylaş menyusu açılmadı. Aşağıdakı şəkli saxlayın və ya WhatsApp keçidindən istifadə edin.','Paylaşım menüsü açılmadı. Aşağıdaki görseli kaydedin veya WhatsApp bağlantısını kullanın.','Меню недоступно. Сохраните изображение ниже или используйте ссылку WhatsApp.','Share menu unavailable. Save the image below or use the WhatsApp link.','قائمة المشاركة غير متاحة. احفظ الصورة أدناه أو استخدم رابط واتساب.'],long:['Mətn şəkil üçün çox uzundur. Tam duanı mətn kimi paylaşın.','Metin görsel için çok uzun. Tam duayı metin olarak paylaşın.','Текст слишком длинный для картинки. Поделитесь полным текстом.','Too long for one image. Share the complete text instead.','النص طويل لصورة واحدة. شارك النص الكامل.']};
function ds(k){return duaShareCopy[k]?.[['az','tr','ru','en','ar'].indexOf(lang())]||duaShareCopy[k]?.[0]||k}
let selectedDuaShare=null;
function shareDuaData(ref){if(ref==='ramadan-iftar')return {title:rm('iftarDua'),arabic:'ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ',meaning:rm('duaMeaning'),source:'Abu Dawud 2357',ref};if(String(ref).startsWith('lib-'))return shareDuaData(String(ref).slice(4));if(/^\d+$/.test(String(ref))){const d=allDuas().find(d=>d.id===Number(ref));return d?{...d,ref:String(ref)}:null}const d=bookEntries().find(d=>d.id===ref&&d.kind==='personal');return d?{title:d.title,arabic:'',meaning:d.body,source:'',ref}:null}
function shareDuaText(d){return [d.title,d.arabic,d.meaning,d.source,'SHAMS'].filter(Boolean).join('\n\n')}
function duaShareButton(ref){return `<button class="share-dua-icon" data-dua-ref="${esc(String(ref))}" onclick="openDuaShare(this.dataset.duaRef)" aria-label="${ds('share')}">${uiIcon('share')}</button>`}
function openDuaShare(ref){const d=shareDuaData(ref);if(!d)return;selectedDuaShare=d;const text=shareDuaText(d);showContentModal(modalHeading(ds('share'))+`<div class="dua-share-preview share-dua-body" dir="auto">${esc(text)}</div><p class="notice">${ds('status')}</p><div class="dua-share-options"><button class="goldbtn" onclick="shareSelectedDuaImage()">${uiIcon('share')}${ds('image')}</button><button class="secondarybtn" onclick="shareSelectedDuaText()">${uiIcon('share')}${ds('text')}</button><button class="secondarybtn" onclick="copySelectedDua()">${uiIcon('book')}${ds('copy')}</button><a class="secondarybtn" href="https://wa.me/?text=${encodeURIComponent(text)}" target="_blank" rel="noopener">WhatsApp</a></div><div id="duaImagePreview"></div><p id="duaShareStatus" class="notice" role="status"></p>`)}
function duaShareStatus(text){const e=document.querySelector('#duaShareStatus');if(e)e.textContent=text}
async function copySelectedDua(){if(!selectedDuaShare)return;try{await navigator.clipboard.writeText(shareDuaText(selectedDuaShare));duaShareStatus(ds('copied'))}catch{duaShareStatus(ds('fallback'))}}
async function shareSelectedDuaText(){if(!selectedDuaShare)return;const title=selectedDuaShare.title,text=shareDuaText(selectedDuaShare);try{if(window.ShamsAndroid?.shareDuaText){window.ShamsAndroid.shareDuaText(title,text);return}if(navigator.share){await navigator.share({title,text});return}duaShareStatus(ds('fallback'))}catch(e){if(e.name!=='AbortError')duaShareStatus(ds('fallback'))}}
async function shareSelectedDuaImage(){if(!selectedDuaShare)return;const d=selectedDuaShare;if(shareDuaText(d).length>5000){duaShareStatus(ds('long'));return}try{const data=await screenDuaImage(d);const host=document.querySelector('#duaImagePreview');if(host){const img=document.createElement('img');img.className='dua-share-image';img.src=data;img.alt=d.title;const link=document.createElement('a');link.href=data;link.download='SHAMS-dua.png';link.className='secondarybtn';link.textContent=up('download');host.replaceChildren(img,link)}if(window.ShamsAndroid?.shareDuaImage){window.ShamsAndroid.shareDuaImage(data,d.title);return}if(typeof File!=='undefined'&&navigator.canShare&&navigator.share){const binary=atob(data.split(',')[1]),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0)),file=new File([bytes],'SHAMS-dua.png',{type:'image/png'});if(navigator.canShare({files:[file]})){await navigator.share({title:d.title,files:[file]});return}}duaShareStatus(ds('fallback'))}catch(e){if(e.name!=='AbortError')duaShareStatus(ds('fallback'))}}
function initializeDuaSharing(){const detail=duaDetail;duaDetail=function(id){const html=detail(id);return allDuas().some(d=>d.id===id)?html.replace('<article class="dua-reader">',`<div class="dua-share-actions">${duaShareButton(id)}</div><article class="dua-reader">`):html};const banner=dailyDuaBanner;dailyDuaBanner=function(expanded=false){const d=allDuas()[dailyDuaIndex()];return `<div class="daily-share-row">${banner(expanded)}${duaShareButton(d.id)}</div>`};const ramadan=ramadanDua;ramadanDua=function(){return ramadan().replace('</details>',`<div class="dua-share-actions">${duaShareButton('ramadan-iftar')}</div></details>`)};const card=bookCard;bookCard=function(d){return card(d).replace('</footer>',duaShareButton(d.id)+'</footer>')};const open=openBookDua;openBookDua=function(id){open(id);const e=document.querySelector('#contentModal .module-actions');if(e)e.insertAdjacentHTML('afterbegin',duaShareButton(id))};const data=screenDuaPage;screenDuaPage=function(){return data().replace('<div class="screen-actions">',`<div class="screen-actions">${duaShareButton(screenDua().id)}`)}}
